use vstd::prelude::*;

verus! {

// Specification function to check if an integer is odd
spec fn is_odd(x: i32) -> bool {
    x % 2 != 0
}

// Specification function to check if all elements before index i are even
spec fn all_even_before(a: Seq<i32>, i: int) -> bool {
    forall|j: int| 0 <= j < i ==> !is_odd(a[j])
}

fn find_first_odd(a: &[i32]) -> (result: (bool, usize))
    ensures
        // If found is false, all elements are even
        !result.0 ==> forall|i: int| 0 <= i < a@.len() ==> !is_odd(a@[i]),
        // If found is true, the index is valid, the element at index is odd,
        // and all elements before it are even
        result.0 ==> {
            &&& result.1 < a@.len()
            &&& is_odd(a@[result.1 as int])
            &&& all_even_before(a@, result.1 as int)
        },
{
    let mut i: usize = 0;
    
    while i < a.len()
        invariant
            i <= a.len(),
            // All elements before i are even
            all_even_before(a@, i as int),
        decreases
            a.len() - i,
    {
        if a[i] % 2 != 0 {
            // Found an odd element
            assert(is_odd(a@[i as int]));
            assert(all_even_before(a@, i as int));
            return (true, i);
        }
        
        // Prove that a[i] is even for the next iteration
        assert(!is_odd(a@[i as int]));
        
        i = i + 1;
    }
    
    // No odd element found - all elements are even
    assert(i == a.len());
    assert(forall|j: int| 0 <= j < a@.len() ==> !is_odd(a@[j])) by {
        assert(all_even_before(a@, i as int));
    }
    
    (false, 0)
}

}

